export const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const say=(lang,en,hi)=>lang==='hi'?hi:en;
export const innerlyMission={en:'Help people understand their current state of mind, identify thinking and behavioural patterns that may contribute to mental stress, and discover practical ways to improve their mental well-being, resilience and overall quality of life.',hi:'लोगों को अपने मन की वर्तमान स्थिति समझने, सोच और व्यवहार के उन तरीकों को पहचानने में मदद करना जो मानसिक तनाव बढ़ा सकते हैं, और मानसिक स्वास्थ्य, मुश्किलों से उबरने की क्षमता तथा जीवन की गुणवत्ता बेहतर बनाने के व्यावहारिक तरीके खोजना।'};
const sampleAnswers=[2,2,1,1,2,1,2,1,2,0];
const symptoms=l=>l==='hi'?['घबराहट','चिंता रोकना','उदासी','रुचि की कमी']:['Feeling on edge','Controlling worry','Feeling low','Little enjoyment'];
export const themes={
 stress:{en:['Stress','A lot on your mind?','When everyday demands feel heavy, notice what is taking the most space.','Choose one task that can wait today.'],hi:['तनाव','मन पर बहुत बोझ है?','रोज़मर्रा की माँगें भारी लगें तो पहचानें कि सबसे ज़्यादा बोझ किस बात का है।','आज एक ऐसा काम चुनें जो इंतज़ार कर सकता है।']},
 mood:{en:['Low mood','Not feeling like yourself?','A check-in can help put words to low mood and a loss of enjoyment.','Share how you have been feeling with someone you trust.'],hi:['उदासी','पहले जैसा महसूस नहीं हो रहा?','Check-in से उदासी और चीज़ों में मन न लगने को समझने की शुरुआत करें।','अपने हाल के बारे में किसी भरोसेमंद व्यक्ति से बात करें।']},
 worry:{en:['Worry','Thoughts that keep circling?','Notice how often worry has been showing up over the last two weeks.','Feel your feet on the ground and notice what is around you.'],hi:['चिंता','बार-बार वही विचार आते हैं?','देखें पिछले दो सप्ताह में चिंता कितनी बार साथ रही।','पैरों को ज़मीन पर महसूस करें और आसपास की चीज़ों पर ध्यान दें।']},
 anger:{en:['Anger','What happens before you react?','Understand your response without judging yourself for having a feeling.','If it is safe, pause and count slowly to ten before responding.'],hi:['गुस्सा','प्रतिक्रिया से पहले क्या होता है?','गुस्सा महसूस करने के लिए खुद को दोष दिए बिना अपना तरीका समझें।','सुरक्षित हो तो जवाब देने से पहले रुकें और धीरे-धीरे दस तक गिनें।']},
 relationships:{en:['Relationships','How do you feel around others?','Your feelings have a place in your relationships, too. Notice when you feel heard, tense or distant.','If it feels safe, share one feeling and one thing you need.'],hi:['रिश्ते','अपनों के साथ कैसा महसूस होता है?','रिश्तों में आपके एहसास भी मायने रखते हैं। ध्यान दें कब सुना हुआ, तनाव में या दूर महसूस करते हैं।','सुरक्षित लगे तो अपना एक एहसास और एक ज़रूरत बताएँ।']},
 sleep:{en:['Sleep','Rest that does not feel restful?','Notice when sleep difficulties spill into your day.','Try a quieter wind-down and a consistent wake-up time.'],hi:['नींद','आराम के बाद भी थकान है?','देखें नींद की परेशानी दिन में कैसे असर करती है।','सोने से पहले माहौल शांत और उठने का समय नियमित रखें।']}
};
export function screenBars(scores,l='en',interactive=false){return `<div class="mh-screen-bars">${[['anxiety',say(l,'Worry & anxiety','चिंता और घबराहट'),'#598caa'],['mood',say(l,'Low mood & interest','उदासी और रुचि'),'#9b88ac']].map(([key,label,color])=>`<${interactive?'button':'div'} class="mh-screen-row" ${interactive?`data-screen-detail="${key}" aria-pressed="${key==='anxiety'}"`:''}><span class="mh-bar-label"><strong>${label}</strong><b>${scores[key]}<small> / 6</small></b></span><span class="mh-bar-track"><i style="width:${scores[key]/6*100}%;background:${color}"></i><span class="mh-threshold"></span></span><span class="mh-bar-ends"><span>0</span><span>${say(l,'Follow-up threshold: 3','आगे बातचीत का संकेत: 3')}</span><span>6</span></span></${interactive?'button':'div'}>`).join('')}</div>`;}
export function responseBars(answers,l='en'){
 l=displayLanguage(l);return `<div class="mh-responses">${answers.slice(0,4).map((value,i)=>`<div><div><span>${symptoms(l)[i]}</span><strong>${frequency[l][value]}</strong></div><div class="mh-response-track"><span style="width:${value/3*100}%"></span></div></div>`).join('')}</div>`;}
export function historyChart(records,l='en',sample=false,historyLanguage=l){
 const history=sample?[{scores:{total:8},createdAt:'2026-01-01',id:'sample1'},{scores:{total:5},createdAt:'2026-01-15',id:'sample2'},{scores:{total:6},createdAt:'2026-01-29',id:'sample3'}]:compatibleHistory(records,historyLanguage);
 if(!history.length)return `<div class="mh-empty">${say(l,'Your first saved check-in will start your timeline.','आपका पहला सेव किया check-in इस यात्रा की शुरुआत होगा।')}</div>`;
 const first=Date.parse(history[0].createdAt),span=Date.parse(history.at(-1).createdAt)-first;
 const point=(r)=>[history.length===1?220:48+(Date.parse(r.createdAt)-first)/span*344,215-r.scores.total/12*170];
 return `<div class="mh-timeline"><svg viewBox="0 0 440 270" role="img" aria-label="${esc(say(l,sample?'Illustrative PHQ-4 totals across three fictional check-ins: 8, 5, 6.':'Your saved PHQ-4 totals over time. Exact values are listed below.',sample?'तीन काल्पनिक check-ins के PHQ-4 totals: 8, 5, 6।':'आपके सेव किए PHQ-4 totals। नीचे सभी मान दिए हैं।'))}">${[0,3,6,9,12].map(n=>`<path d="M48 ${215-n/12*170}H392" stroke="#dfe7ec" stroke-dasharray="3 5"/><text x="31" y="${220-n/12*170}" text-anchor="end">${n}</text>`).join('')}${history.length>1?`<polyline class="mh-chart-draw" points="${history.map(r=>point(r).join(',')).join(' ')}" fill="none" stroke="#538b99" stroke-width="3"/>`:''}${history.map((r,i)=>{const [x,y]=point(r);return `<circle cx="${x}" cy="${y}" r="6" fill="#538b99" stroke="white" stroke-width="2"/><text x="${x}" y="${y-14}" text-anchor="middle">${r.scores.total}</text><text x="${x}" y="246" text-anchor="middle">${sample?`${i+1}`:i===0||i===history.length-1?new Date(r.createdAt).toLocaleDateString(l,{day:'numeric',month:'short'}):''}</text>`;}).join('')}</svg><p class="mh-chart-note">${say(l,sample?'Example only · Three fictional check-ins':history.length===1?'One check-in is a starting point, not a trend.':'PHQ-4 total / 12 · Lower means fewer reported symptoms.',sample?'सिर्फ़ उदाहरण · तीन काल्पनिक check-ins':history.length===1?'एक check-in शुरुआत है, trend नहीं।':'PHQ-4 कुल / 12 · कम अंक यानी कम बताए गए लक्षण।')}</p>${!sample?`<div class="mh-history-points" role="group" aria-label="${say(l,'Read a saved check-in','सेव किया check-in देखें')}">${history.map(r=>`<button data-history-point="${esc(r.id)}">${new Date(r.createdAt).toLocaleDateString(l,{day:'numeric',month:'short'})} <strong>${r.scores.total}/12</strong></button>`).join('')}</div>`:''}</div>`;
}
export function sampleReport(view='snapshot',l='en'){return workbookSample(view,l);}
export function themeMarkup(key='stress',l='en'){
 const c=(themes[key]||themes.stress)[l];return `<div class="mh-theme-story"><div class="mh-theme-copy"><span class="mh-kicker">${say(l,'START WITH WHAT YOU NOTICE','जिस बात पर ध्यान जाए, वहीं से शुरू करें')}</span><h3>${c[1]}</h3><p>${c[2]}</p></div><div class="mh-theme-action"><div><span class="mh-kicker">${say(l,'ONE GENTLE START','एक छोटी शुरुआत')}</span><p>${c[3]}</p>${key==='relationships'?`<a class="mh-guidance-source" href="${relationshipSource}" target="_blank" rel="noopener">${say(l,'Relationships & wellbeing · NHS','रिश्ते और wellbeing · NHS')} ↗</a>`:''}</div></div><button class="mh-secondary" data-action="begin">${say(l,'Start My Test','अपना टेस्ट शुरू करें')} →</button></div>${feelingVisual(key,l)}`;
}
export function mentalHomeMarkup({language='en'}={}){return innerlyHome({language,mission:innerlyMission[displayLanguage(language)]});}
export function quizMarkup(answers,l='en',savedDraft=false){
 const done=completedCount(answers),percent=growthState(answers).percent,t=(key,en,hi)=>questionUI(l,key,en,hi),g=questionnaireLocale(l);
 return `<section class="mh-checkin"><div class="mh-quiz-top"><div><p class="mh-kicker">${t('Questions','YOUR PRIVATE CHECK-IN','आपका निजी CHECK-IN')}</p><h1>${t('A little closer to yourself.','A little closer to yourself.','खुद के थोड़ा और करीब।')}</h1></div><button class="mh-link" data-action="home">${t('Explore','Back home','होम पर जाएँ')}</button></div>
 <div class="mh-progress"><div class="mh-progress-layout">${growthMarkup(answers,l)}<div class="mh-progress-summary"><strong id="mh-progress-percent">${percent}<span>%</span></strong><span>${t('complete','complete','पूरा')}</span><small id="mh-progress-label">${done} / ${QUESTION_TOTAL}</small></div></div><progress id="mh-progress" value="${done}" max="${QUESTION_TOTAL}" aria-label="${t('completed','Questions completed','पूरे हुए सवाल')}" aria-valuetext="${percent}% · ${done} / ${QUESTION_TOTAL}"></progress><div class="mh-progress-tools"><button data-action="review" class="mh-link">${t('Questions','Review answers','जवाब देखें')}</button><button data-action="break" class="mh-pause-button" ${done?'':'disabled'}>${t('Save & take a break','Save & take a break','सेव करें और विराम लें')} <span aria-hidden="true">Ⅱ</span></button></div><span class="mh-draft-status" id="mh-draft-status" role="status">${savedDraft?t('saved','Saved in this browser','इसी browser में सेव है'):''}</span></div>
 <p class="mh-flow-help">${batchCopy(l).help}</p><p class="mh-reflection-notice">${esc(g.notice)}</p>
 <div class="mh-question-list">${questionBank.map((q,i)=>{const reflection=true;return `<fieldset id="mh-q-${i}" class="mh-question${answers[i]!==null?' answered':''}"><legend><span class="mh-q-number">${i+1}.</span> ${esc(q.texts[l])}</legend>
 ${reflection?`<div class="mh-scale-ends" aria-hidden="true"><span>${esc(questionChoices(i,l)[0])}</span><span>${esc(questionChoices(i,l)[4])}</span></div>`:''}
 <div class="mh-options${reflection?' mh-reflection-options':q.options?' mh-context-options':''}">${questionChoices(i,l).map((text,v)=>`<label><input type="radio" name="mental-${i}" value="${v}" data-answer="${i}" ${answers[i]===v?'checked':''}><span class="mh-choice-dot" aria-hidden="true"></span><span class="mh-frequency-caption">${esc(text)}</span></label>`).join('')}</div></fieldset>`;}).join('')}</div>
 <p class="mh-form-message" id="mh-form-message" role="status"></p><div class="mh-quiz-actions"><button class="mh-secondary" data-action="unanswered">${t('Answer remaining questions →','Go to an unanswered question','बाकी सवाल पर जाएँ')} ↑</button><button class="mh-primary" data-action="finish">${t('See results','See my report','मेरी report देखें')} →</button></div>
 <p class="mh-footnote">${esc(coverageNotice(l))}</p></section>`;
}
export function reflectionMarkup(report,l='en'){
 if(!report.reflection)return '';const scores=reflectionScores(report.reflection.answers),traits=l==='hi'?hindiTraits:reflectionTraits;
 return `<details class="mh-method mh-personal-preferences"><summary>${say(l,'Your everyday preferences · 36 reflection answers','आपके रोज़मर्रा के तरीके · 36 reflection जवाब')}</summary><p>${say(l,'These original personality questions describe preferences. Their scores are separate from your mental-health screening and are not clinically validated. Higher is not better.','ये पुराने personality सवाल आपकी पसंद और तरीकों की झलक देते हैं। इनके scores mental-health screening से अलग हैं और clinically validated नहीं हैं। ज़्यादा score बेहतर होने का संकेत नहीं है।')}</p><div class="mh-preference-bars">${traits.map((t,i)=>`<div><strong>${t.name}</strong><div class="mh-preference-track"><i style="left:${scores[i]}%"></i></div><div class="mh-preference-ends"><span>${t.low}</span><span>${t.high}</span></div><p>${say(l,'Position','स्थिति')}: ${scores[i]} / 100</p></div>`).join('')}</div></details>`;
}
export function screeningDetail(report,key,l='en'){
 const score=screenScores(report.answers)[key],name=key==='anxiety'?'GAD-2':'PHQ-2';return `<strong>${name}: ${score} / 6</strong><p>${say(l,score>=3?'This reaches the screening threshold for further assessment. Consider discussing these symptoms with a qualified professional.':'This is below the screening threshold. It does not rule out a mental-health condition; seek support if you are concerned or daily life is affected.',score>=3?'यह आगे जाँच के लिए screening सीमा तक पहुँचता है। इन लक्षणों पर किसी योग्य पेशेवर से बात करें।':'यह screening सीमा से नीचे है। इससे mental-health condition न होने की पुष्टि नहीं होती। चिंता हो या रोज़मर्रा पर असर हो तो मदद लें।')}</p>`;
}
export function reportMarkup(report,saved,l='en',view='snapshot',selection={}){
 if(report.version===INNERLY_V1_VERSION&&!selection.unlocked)return workbookReportPreview(report,l,selection.preview);
 if(report.version===INNERLY_V1_VERSION)return workbookReportMarkup(report,l,view,selection.dimension||'dimension-1',saved.some(r=>r.id===report.id),saved,selection.question??0);
 if(report.version===REFLECTION60_VERSION)return reflectionReportMarkup(report,l,view,'structure',saved.some(r=>r.id===report.id));
 l=displayLanguage(l);
 const s=screenScores(report.answers),level=supportLevel(report),history=[...saved.filter(r=>r.id!==report.id),report],steps=suggestedSteps(report),date=new Date(report.createdAt).toLocaleDateString(l,{day:'numeric',month:'long',year:'numeric'});
 const bandLabels={minimal:say(l,'Minimal reported distress','बहुत कम बताए गए लक्षण'),mild:say(l,'Mild reported distress','हल्के बताए गए लक्षण'),moderate:say(l,'Moderate reported distress','मध्यम स्तर के बताए गए लक्षण'),severe:say(l,'High reported distress','ज़्यादा बताए गए लक्षण')};
 return `<section class="mh-report"><div class="mh-report-heading"><p class="mh-kicker">${say(l,'YOUR MENTAL-HEALTH CHECK-IN','आपका MENTAL-HEALTH CHECK-IN')} · ${date}</p><h1>${say(l,level==='reflect'?'A little more understanding.':'You do not have to figure it out alone.',level==='reflect'?'खुद की थोड़ी बेहतर समझ।':'सब कुछ अकेले सँभालना ज़रूरी नहीं।')}</h1><p>${say(l,'Your wellbeing answers describe the past two weeks. They do not define you.','आपके wellbeing जवाब पिछले दो सप्ताह के बारे में हैं। ये आपकी पूरी पहचान नहीं हैं।')}</p></div><div class="mh-summary"><div class="mh-score"><strong>${s.total}<small> / 12</small></strong><span>PHQ-4</span></div><div><h2>${bandLabels[s.band]}</h2><p>${say(l,level==='soon'?'Please seek professional support soon, especially if these difficulties are affecting daily life.':level==='discuss'?'A conversation with a qualified professional could help you understand these symptoms and their impact.':'You reported relatively few anxiety and depressive symptoms. You can still ask for support whenever you need it.',level==='soon'?'जल्द किसी योग्य पेशेवर से मदद लें, खासकर अगर इन मुश्किलों का रोज़मर्रा पर असर पड़ रहा है।':level==='discuss'?'किसी योग्य पेशेवर से बातचीत इन लक्षणों और उनके असर को समझने में मदद कर सकती है।':'आपने चिंता और उदासी के अपेक्षाकृत कम लक्षण बताए। ज़रूरत महसूस हो तो फिर भी मदद ले सकते हैं।')}</p></div></div><p class="mh-report-limit">${say(l,'Screening is not a diagnosis. A low score does not rule out difficulties or tell us whether someone is safe.','Screening diagnosis नहीं है। कम score मुश्किलों या किसी के असुरक्षित होने की संभावना को खारिज नहीं करता।')}</p>${report.language!=='en'?`<p class="mh-translation-note">${say(l,`Question language: ${esc(languageName(report.language))}. This editorial ${report.language==='hi'?'Hindi ':''}translation has not been independently validated in this app. Discuss the scores with a professional before making health decisions.`,`सवालों की भाषा: ${esc(languageName(report.language))}। इस संपादकीय अनुवाद का इस app में स्वतंत्र validation नहीं हुआ है। स्वास्थ्य से जुड़े निर्णय से पहले scores पर पेशेवर से बात करें।`)}</p>`:''}
 <div class="mh-report-visual"><div class="mh-demo-tabs" role="group" aria-label="${say(l,'Your report views','आपकी report के नज़रिए')}">${[['snapshot','Mood & worry','उदासी और चिंता'],['days','My recent days','मेरे हाल के दिन'],['journey','Over time','समय के साथ']].map(([v,en,hi])=>`<button data-report-view="${v}" aria-pressed="${v===view}">${say(l,en,hi)}</button>`).join('')}</div><div id="mh-personal-chart">${view==='journey'?historyChart(history,l,false,report.language):view==='days'?responseBars(report.answers,l):`${screenBars(s,l,true)}<div class="mh-score-reading" id="mh-score-reading" aria-live="polite">${screeningDetail(report,'anxiety',l)}</div>`}</div><p class="mh-chart-note">${say(l,'Based on your answers, not comparisons with other people or countries.','आपके जवाबों पर आधारित; दूसरे लोगों या देशों से तुलना नहीं।')}</p></div>
 <section class="mh-context"><div class="mh-section-heading"><div><p class="mh-kicker">${say(l,'THE EVERYDAY CONTEXT','रोज़मर्रा का संदर्भ')}</p><h2>${say(l,'What else you noticed.','आपने और क्या महसूस किया।')}</h2></div><p>${say(l,'These answers add context.<br>They are not diagnostic scores.','ये जवाब संदर्भ देते हैं।<br>ये diagnostic scores नहीं हैं।')}</p></div><div class="mh-context-grid">${[[4,'Stress','तनाव'],[5,'Sleep','नींद'],[6,'Anger response','गुस्से में प्रतिक्रिया'],[7,'Daily impact','रोज़मर्रा पर असर'],[8,'Where it feels heavy','कहाँ बोझ महसूस हुआ'],[9,'Support you chose','आपकी चुनी मदद']].map(([i,en,hi])=>`<article><h3>${say(l,en,hi)}</h3><p>${report.answers[i]==='skip'?say(l,'Not answered','जवाब नहीं दिया'):answerOptions(i,l)[report.answers[i]]}</p></article>`).join('')}</div></section>
 ${reflectionMarkup(report,l)}<section class="mh-next-steps"><p class="mh-kicker">${say(l,'SMALL STEPS, NOT MORE PRESSURE','छोटे कदम, कोई नया दबाव नहीं')}</p><h2>${say(l,'Where you could begin.','यहाँ से शुरुआत कर सकते हैं।')}</h2><div>${steps.map((key,i)=>{const c=stepContent[key][l];return `<article><span>${String(i+1).padStart(2,'0')}</span><h3>${c[0]}</h3><p>${c[1]}</p><a href="${stepContent[key].source}" target="_blank" rel="noopener">${say(l,'Read the guidance','मार्गदर्शन पढ़ें')} ↗</a></article>`;}).join('')}</div></section>
 <details class="mh-method"><summary>${say(l,'How this report was made','यह report कैसे बनी')}</summary><p>${say(l,'The four symptom-frequency answers in the wellbeing section form the PHQ-4 (0–12). The first two symptom items form GAD-2 and the next two form PHQ-2 (each 0–6); a subscore of 3 or more is a signal for further assessment. Published PHQ-4 distress bands: 0–2 normal/minimal, 3–5 mild, 6–8 moderate, 9–12 severe. These are screening bands, not a diagnosis or a percentage of mental health.','Wellbeing section के चार symptom-frequency जवाब PHQ-4 (0–12) बनाते हैं। पहले दो GAD-2 और अगले दो PHQ-2 (दोनों 0–6) हैं। किसी subscore का 3 या अधिक होना आगे जाँच का संकेत है। प्रकाशित PHQ-4 distress ranges: 0–2 normal/minimal, 3–5 mild, 6–8 moderate, 9–12 severe। ये screening ranges हैं, diagnosis या mental health का प्रतिशत नहीं।')}</p><p>${say(l,'The six context questions do not change screening scores. A history uses only actual saved check-ins in the same language and version, keeping the latest per day. Consecutive two-week windows can overlap. Changes are not proof of treatment effects.','छह संदर्भ सवाल screening scores नहीं बदलते। History में उसी version और भाषा के असली सेव check-ins आते हैं, हर दिन का सबसे हाल का। दो सप्ताह की अवधियाँ आपस में मिल सकती हैं। बदलाव इलाज के असर का प्रमाण नहीं है।')}</p><p>PHQ-4: Kroenke, Spitzer, Williams & Löwe (2009). PHQ/GAD instruments developed with an educational grant from Pfizer. <a href="${PHQ_SOURCE}" target="_blank" rel="noopener">${say(l,'Scoring and attribution','Scoring और स्रोत')} ↗</a></p></details><div class="mh-report-actions"><button class="mh-primary" data-action="save">${say(l,saved.some(r=>r.id===report.id)?'Saved on this device':'Save on this device',saved.some(r=>r.id===report.id)?'इस device पर सेव है':'इस device पर सेव करें')}</button><button class="mh-secondary" data-action="print">${say(l,'Print / save PDF','Print / PDF सेव करें')}</button><button class="mh-link" data-action="begin">${say(l,'Start My Test','अपना टेस्ट शुरू करें')}</button></div><p class="mh-footnote">${say(l,'Your summary, guidance and full report are free for now.','आपकी summary, guidance और पूरी report अभी मुफ़्त हैं।')}</p><div id="mh-report-status" role="status" class="mh-form-message"></div></section>`;
}
